class MyCircularDeque {
    private int[] data;
    private int front, rear, cap;
    public MyCircularDeque(int k) { cap = k + 1; data = new int[cap]; }
    public boolean insertFront(int value) {
        if (isFull()) return false;
        front = (front - 1 + cap) % cap; data[front] = value; return true;
    }
    public boolean insertLast(int value) {
        if (isFull()) return false;
        data[rear] = value; rear = (rear + 1) % cap; return true;
    }
    public boolean deleteFront() { if (isEmpty()) return false; front = (front + 1) % cap; return true; }
    public boolean deleteLast() { if (isEmpty()) return false; rear = (rear - 1 + cap) % cap; return true; }
    public int getFront() { return isEmpty() ? -1 : data[front]; }
    public int getRear() { return isEmpty() ? -1 : data[(rear - 1 + cap) % cap]; }
    public boolean isEmpty() { return front == rear; }
    public boolean isFull() { return (rear + 1) % cap == front; }
}

class MyCircularDeque {
    private int[] vals, prevs, nexts;
    private int headS, tailS, size, cap, cnt;
    public MyCircularDeque(int k) {
        cap = k; vals = new int[k + 4]; prevs = new int[k + 4]; nexts = new int[k + 4];
        headS = 0; tailS = 1; cnt = 2; size = 0;
        nexts[headS] = tailS; prevs[tailS] = headS;
    }
    public boolean insertFront(int value) {
        if (isFull()) return false;
        int node = cnt++; vals[node] = value;
        int after = nexts[headS];
        nexts[headS] = node; prevs[node] = headS;
        nexts[node] = after; prevs[after] = node;
        size++; return true;
    }
    public boolean insertLast(int value) {
        if (isFull()) return false;
        int node = cnt++; vals[node] = value;
        int before = prevs[tailS];
        nexts[before] = node; prevs[node] = before;
        nexts[node] = tailS; prevs[tailS] = node;
        size++; return true;
    }
    public boolean deleteFront() {
        if (isEmpty()) return false;
        int del = nexts[headS]; int after = nexts[del];
        nexts[headS] = after; prevs[after] = headS;
        size--; return true;
    }
    public boolean deleteLast() {
        if (isEmpty()) return false;
        int del = prevs[tailS]; int before = prevs[del];
        nexts[before] = tailS; prevs[tailS] = before;
        size--; return true;
    }
    public int getFront() { return isEmpty() ? -1 : vals[nexts[headS]]; }
    public int getRear() { return isEmpty() ? -1 : vals[prevs[tailS]]; }
    public boolean isEmpty() { return size == 0; }
    public boolean isFull() { return size == cap; }
}
